$paths = @( "$env:APPDATA\Microsoft\Windows\Start Menu\Programs", "$env:ProgramData\Microsoft\Windows\Start Menu\Programs" ); $results = @(); foreach ($path in $paths) { if (Test-Path $path) { $files = Get-ChildItem -Path $path -Recurse -Filter "*.lnk" | Where-Object { $_.Name -match "Discord|Steam|Antigravity|Cursor" }; foreach ($file in $files) { $shell = New-Object -ComObject WScript.Shell; $shortcut = $shell.CreateShortcut($file.FullName); $results += [PSCustomObject]@{ Name=$file.Name; FullPath=$file.FullName; Target=$shortcut.TargetPath; IconLocation=$shortcut.IconLocation } } } }; $results | ConvertTo-Json
